    h = _fecha_param(hasta, 'hasta')
    if d > h:
        raise HTTPException(422, '"desde" no puede ser posterior a "hasta"')
    if (h - d).days + 1 > 31:
        raise HTTPException(422, 'El período no puede superar los 31 días')
    salida = io.StringIO()
